CREATE TABLE feed_ingredient(ingredient_id BIGINT PRIMARY KEY,farm_id BIGINT NOT NULL,ingredient_name VARCHAR(100) NOT NULL,ingredient_type VARCHAR(30),dry_matter_pct DECIMAL(6,2),crude_protein_pct DECIMAL(6,2),energy_value DECIMAL(10,3),ndf_pct DECIMAL(6,2),calcium_pct DECIMAL(6,2),phosphorus_pct DECIMAL(6,2),unit_price DECIMAL(10,2),status VARCHAR(20) NOT NULL DEFAULT 'ENABLED',remark VARCHAR(500),created_by BIGINT,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_by BIGINT,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,version INT NOT NULL DEFAULT 0,CONSTRAINT uk_feed_ingredient_name UNIQUE(farm_id,ingredient_name),INDEX idx_feed_ingredient_status(farm_id,status));
CREATE TABLE ration_formula(formula_id BIGINT PRIMARY KEY,farm_id BIGINT NOT NULL,formula_name VARCHAR(100) NOT NULL,version_no INT NOT NULL DEFAULT 1,target_type VARCHAR(20) NOT NULL DEFAULT 'HERD',target_object_id BIGINT NULL,daily_intake_kg DECIMAL(10,2),source_file VARCHAR(255),status VARCHAR(20) NOT NULL DEFAULT 'DRAFT',remark VARCHAR(500),created_by BIGINT,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_by BIGINT,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,version INT NOT NULL DEFAULT 0,CONSTRAINT uk_ration_formula_version UNIQUE(farm_id,formula_name,version_no),INDEX idx_formula_status(farm_id,status));
CREATE TABLE ration_formula_item(item_id BIGINT PRIMARY KEY,farm_id BIGINT NOT NULL,formula_id BIGINT NOT NULL,ingredient_id BIGINT NOT NULL,ratio_pct DECIMAL(8,4),daily_amount_kg DECIMAL(10,3),sort_no INT NOT NULL DEFAULT 0,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT uk_formula_ingredient UNIQUE(formula_id,ingredient_id));
CREATE TABLE mixing_order(mixing_order_id BIGINT PRIMARY KEY,farm_id BIGINT NOT NULL,formula_id BIGINT NOT NULL,target_herd_id BIGINT NULL,cattle_count INT NOT NULL,feed_date DATE NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'PENDING_CONFIRM',assignee_id BIGINT NULL,confirm_reason VARCHAR(255),created_by BIGINT,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_by BIGINT,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,version INT NOT NULL DEFAULT 0,INDEX idx_mixing_order_date(farm_id,feed_date,status));
CREATE TABLE mixing_order_item(item_id BIGINT PRIMARY KEY,farm_id BIGINT NOT NULL,mixing_order_id BIGINT NOT NULL,ingredient_id BIGINT NOT NULL,planned_amount_kg DECIMAL(12,3) NOT NULL,adjusted_amount_kg DECIMAL(12,3),adjust_reason VARCHAR(255),created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT uk_mixing_order_ingredient UNIQUE(mixing_order_id,ingredient_id));
CREATE TABLE mixing_execution(execution_id BIGINT PRIMARY KEY,farm_id BIGINT NOT NULL,mixing_order_id BIGINT NOT NULL,execution_time DATETIME NOT NULL,executor_id BIGINT NOT NULL,actual_summary TEXT,deviation_note VARCHAR(500),task_id BIGINT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,INDEX idx_mixing_execution_order(farm_id,mixing_order_id));
